// ProfileEditor.tsx
import { useState } from 'react';

type Profile = {
  name: string;
  contact: { email: string; phone: string };
  address: { city: string; street: string };
};
type Section = 'contact' | 'address';

const INITIAL: Profile = { name: 'Ola', contact: { email: 'ola@example.com', phone: '' }, address: { city: 'Łódź', street: '' } };

export function ProfileEditor() {
  const [profile, setProfile] = useState(INITIAL);

  // Pole musi istnieć w wybranej sekcji: updateField('address', 'email', …) to błąd kompilacji.
  function updateField<S extends Section>(section: S, field: keyof Profile[S], value: string) {
    setProfile((p) => ({ ...p, [section]: { ...p[section], [field]: value } }));
  }

  return (
    <form>
      <label>Imię <input value={profile.name} onChange={(e) => setProfile((p) => ({ ...p, name: e.target.value }))} /></label>
      <label>E-mail <input value={profile.contact.email} onChange={(e) => updateField('contact', 'email', e.target.value)} /></label>
      <label>Telefon <input value={profile.contact.phone} onChange={(e) => updateField('contact', 'phone', e.target.value)} /></label>
      <label>Miasto <input value={profile.address.city} onChange={(e) => updateField('address', 'city', e.target.value)} /></label>
      <label>Ulica <input value={profile.address.street} onChange={(e) => updateField('address', 'street', e.target.value)} /></label>
      <pre>{JSON.stringify(profile, null, 2)}</pre>
    </form>
