export function ListColumn({ list, onAdd, onToggle }: ListColumnProps) {
  const [draft, setDraft] = useState('');

  return (
    <section className="column">
      <h3>{list.name} ({list.todos.filter((t) => !t.done).length})</h3>
      <ul>
        {list.todos.map((t) => (
