import {useState} from "react";
export type Expense=Readonly<{id:string;category:string;amountGrosze:number}>;
export function totalsByCategory(expenses:readonly Expense[]):Map<string,number>{const totals=new Map<string,number>();for(const expense of expenses)totals.set(expense.category,(totals.get(expense.category)??0)+expense.amountGrosze);return totals;}
