export function Expenses({initial}:{initial:readonly Expense[]}){const [items,setItems]=useState(initial);const [collapsed,setCollapsed]=useState<ReadonlySet<string>>(()=>new Set());const categories=sortedCategories(items);return <section>{categories.map(([category,total])=><section key={category}><button type="button" aria-expanded={!collapsed.has(category)} onClick={()=>setCollapsed(previous=>{const next=new Set(previous);if(next.has(category))next.delete(category);else next.add(category);return next;})}>{category}: {(total/100).toLocaleString("pl-PL",{style:"currency",currency:"PLN"})}</button>{!collapsed.has(category)&&<ul>{items.filter(item=>item.category===category).map(item=><li key={item.id}>{item.amountGrosze} gr<button type="button" onClick={()=>setItems(previous=>previous.filter(entry=>entry.id!==item.id))}>Usuń</button></li>)}</ul>}</section>)}</section>;}

