export type Todo=Readonly<{id:string;title:string;done:boolean}>;
export type TodoList=Readonly<{id:string;name:string;todos:readonly Todo[]}>;
export type History=Readonly<{versions:readonly (readonly Todo[])[];index:number}>;
export function commitHistory(history:History,change:(todos:readonly Todo[])=>readonly Todo[]):History{const current=history.versions[history.index];if(current===undefined)throw new RangeError("Niepoprawna historia");const next=change(current);return {versions:[...history.versions.slice(0,history.index+1),next],index:history.index+1};}
export function undo(history:History):History{return history.index>0?{...history,index:history.index-1}:history;}
export function redo(history:History):History{return history.index<history.versions.length-1?{...history,index:history.index+1}:history;}

import {useState} from "react";
export type Todo=Readonly<{id:string;title:string;done:boolean}>;
export type TodoList=Readonly<{id:string;name:string;todos:readonly Todo[]}>;
export function addTodo(todos:readonly Todo[],todo:Todo):readonly Todo[]{if(todos.some(item=>item.id===todo.id))throw new Error("Powtórzone id");return [...todos,todo];}
export function prependTodo(todos:readonly Todo[],todo:Todo):readonly Todo[]{if(todos.some(item=>item.id===todo.id))throw new Error("Powtórzone id");return [todo,...todos];}
export function toggleTodo(todos:readonly Todo[],id:string):readonly Todo[]{return todos.map(todo=>todo.id===id?{...todo,done:!todo.done}:todo);}
export function renameTodo(todos:readonly Todo[],id:string,title:string):readonly Todo[]{return todos.map(todo=>todo.id===id?{...todo,title}:todo);}
export function removeTodo(todos:readonly Todo[],id:string):readonly Todo[]{return todos.filter(todo=>todo.id!==id);}
export function insertTodo(todos:readonly Todo[],index:number,todo:Todo):readonly Todo[]{if(!Number.isSafeInteger(index)||index<0||index>todos.length)throw new RangeError("Indeks");if(todos.some(item=>item.id===todo.id))throw new Error("Powtórzone id");return todos.toSpliced(index,0,todo);}
export function moveTodo(todos:readonly Todo[],id:string,direction:-1|1):readonly Todo[]{const from=todos.findIndex(todo=>todo.id===id);const to=from+direction;if(from<0||to<0||to>=todos.length)return todos;const todo=todos[from];return todos.toSpliced(from,1).toSpliced(to,0,todo);}
export function toggleInList(lists:readonly TodoList[],listId:string,todoId:string):readonly TodoList[]{return lists.map(list=>list.id===listId?{...list,todos:toggleTodo(list.todos,todoId)}:list);}
export type History=Readonly<{versions:readonly (readonly Todo[])[];index:number}>;
export function commitHistory(history:History,change:(todos:readonly Todo[])=>readonly Todo[]):History{const current=history.versions[history.index];if(current===undefined)throw new RangeError("Niepoprawna historia");const next=change(current);return {versions:[...history.versions.slice(0,history.index+1),next],index:history.index+1};}
export function undo(history:History):History{return history.index>0?{...history,index:history.index-1}:history;}
export function redo(history:History):History{return history.index<history.versions.length-1?{...history,index:history.index+1}:history;}
export function UndoableTodos({initial}:{initial:readonly Todo[]}){const [history,setHistory]=useState<History>({versions:[initial],index:0});const todos=history.versions[history.index];return <section><button type="button" disabled={history.index===0} onClick={()=>setHistory(previous=>undo(previous))}>Cofnij</button><button type="button" disabled={history.index===history.versions.length-1} onClick={()=>setHistory(previous=>redo(previous))}>Ponów</button><ul>{todos.map(todo=><li key={todo.id}><label><input type="checkbox" checked={todo.done} onChange={()=>setHistory(previous=>commitHistory(previous,current=>toggleTodo(current,todo.id)))}/>{todo.title}</label><button type="button" onClick={()=>setHistory(previous=>commitHistory(previous,current=>removeTodo(current,todo.id)))}>Usuń</button></li>)}</ul></section>;}

